from dataclasses import dataclass
from functools import cache

@dataclass(frozen=True, slots=True)
class Glyph:                                      # intrinsic, immutable
    code: str; w: int; h: int

@cache
def glyph(code: str, w: int, h: int) -> Glyph:    # factory: one instance per key
    return Glyph(code, w, h)

cell = (glyph("A", 8, 12), 10, 20)                # (shared glyph, x, y)
